import{_ as a,o as e,c as t,a2 as i}from"./chunks/framework.CZqXuAiL.js";const k=JSON.parse('{"title":"The Extractor","description":"Browse backups stored in S3 and download any one to your machine, with optional decompression and restore commands.","frontmatter":{"title":"The Extractor","description":"Browse backups stored in S3 and download any one to your machine, with optional decompression and restore commands."},"headers":[],"relativePath":"s3-database-storage-for-vps/user-guide/extractor.md","filePath":"s3-database-storage-for-vps/user-guide/extractor.md","lastUpdated":null}'),n={name:"s3-database-storage-for-vps/user-guide/extractor.md"};function o(p,s,r,l,h,d){return e(),t("div",null,[...s[0]||(s[0]=[i(`<h1 id="the-extractor" tabindex="-1">The Extractor <a class="header-anchor" href="#the-extractor" aria-label="Permalink to &quot;The Extractor&quot;">​</a></h1><p>The extractor is how you get a backup back. It logs in to S3, shows a tree of every stored backup grouped by database, and downloads the one you choose.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> s3dbbackup</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> extract</span></span></code></pre></div><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><h3 id="_1-connect" tabindex="-1">1. Connect <a class="header-anchor" href="#_1-connect" aria-label="Permalink to &quot;1. Connect&quot;">​</a></h3><p>It asks whether to use the <strong>saved connection</strong> from this server&#39;s config, or to enter fresh credentials (handy when restoring on a different machine, or pulling from a bucket this server didn&#39;t create).</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Use the saved S3 connection from this server&#39;s config? [Y/n]</span></span></code></pre></div><p>If you choose fresh credentials it prompts for endpoint, region, access key, secret, bucket, folder/prefix, and path-style — then tests the connection.</p><h3 id="_2-browse" tabindex="-1">2. Browse <a class="header-anchor" href="#_2-browse" aria-label="Permalink to &quot;2. Browse&quot;">​</a></h3><p>It prints a tree of every backup, grouped by database type and name, each line numbered:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Available backups</span></span>
<span class="line"><span>├── mysql</span></span>
<span class="line"><span>│   └── wordpress (3)</span></span>
<span class="line"><span>│       ├── #1 2026-06-30_18-00-02.sql.gz   3.21 MiB · 2026-06-30 18:00:02</span></span>
<span class="line"><span>│       ├── #2 2026-06-29_18-00-02.sql.gz   3.19 MiB · 2026-06-29 18:00:02</span></span>
<span class="line"><span>│       └── #3 2026-06-28_18-00-02.sql.gz   3.18 MiB · 2026-06-28 18:00:02</span></span>
<span class="line"><span>└── postgresql</span></span>
<span class="line"><span>    └── app_production (2)</span></span>
<span class="line"><span>        ├── #4 2026-06-30_18-00-01.sql.gz  12.84 MiB · 2026-06-30 18:00:01</span></span>
<span class="line"><span>        └── #5 2026-06-29_18-00-01.sql.gz  12.71 MiB · 2026-06-29 18:00:01</span></span></code></pre></div><h3 id="_3-choose" tabindex="-1">3. Choose <a class="header-anchor" href="#_3-choose" aria-label="Permalink to &quot;3. Choose&quot;">​</a></h3><p>Type the <strong><code>#number</code></strong>, or paste a full key or filename:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Which backup do you want to extract? #4</span></span></code></pre></div><h3 id="_4-download" tabindex="-1">4. Download <a class="header-anchor" href="#_4-download" aria-label="Permalink to &quot;4. Download&quot;">​</a></h3><p>Choose a target directory (defaults to the current directory). The file is downloaded there:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Extract to which directory? /root/restores</span></span>
<span class="line"><span>[*] Downloading s3dbbackup/postgresql/app_production/2026-06-30_18-00-01.sql.gz → /root/restores/2026-06-30_18-00-01.sql.gz</span></span>
<span class="line"><span>✓ Saved to /root/restores/2026-06-30_18-00-01.sql.gz</span></span></code></pre></div><h3 id="_5-decompress-optional" tabindex="-1">5. Decompress (optional) <a class="header-anchor" href="#_5-decompress-optional" aria-label="Permalink to &quot;5. Decompress (optional)&quot;">​</a></h3><p>It can gunzip the <code>.sql.gz</code> for you and prints the exact restore command:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Decompress the .gz now? [y/N] y</span></span>
<span class="line"><span>✓ Decompressed to /root/restores/2026-06-30_18-00-01.sql</span></span>
<span class="line"><span>Restore example (PostgreSQL): psql -U postgres dbname &lt; /root/restores/2026-06-30_18-00-01.sql</span></span>
<span class="line"><span>Restore example (MySQL):      mysql -u root dbname &lt; /root/restores/2026-06-30_18-00-01.sql</span></span></code></pre></div><h2 id="restoring-into-a-database" tabindex="-1">Restoring into a database <a class="header-anchor" href="#restoring-into-a-database" aria-label="Permalink to &quot;Restoring into a database&quot;">​</a></h2><p>After extracting and decompressing:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># PostgreSQL — create the target DB first if needed</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">createdb</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -U</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> postgres</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> app_production_restored</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">psql</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -U</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> postgres</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> app_production_restored</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 2026-06-30_18-00-01.sql</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># MySQL / MariaDB</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mysql</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> root</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;CREATE DATABASE wordpress_restored;&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mysql</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> root</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> wordpress_restored</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 2026-06-30_18-00-02.sql</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>You can also restore straight from the gzip without decompressing to disk:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">gunzip</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 2026-06-30_18-00-02.sql.gz</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> mysql</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> root</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> wordpress_restored</span></span></code></pre></div></div><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Restoring over a live database overwrites data. Restore into a fresh database name first and verify before switching your application over.</p></div>`,25)])])}const g=a(n,[["render",o]]);export{k as __pageData,g as default};
